-- =====================================================================
-- QuickTab Admin — Storage buckets and policies
-- ---------------------------------------------------------------------
-- Run AFTER 0004_rls_policies.sql in the Supabase SQL editor.
--
-- Buckets:
--   * restaurant-assets : logos and cover images
--   * menu-items        : menu item photos
--
-- Both are public-read, 5 MB, JPEG/PNG/WebP. Writes are limited to active
-- staff of the restaurant whose id is the first folder segment:
--   restaurant-assets/{restaurant_id}/logo.{ext}
--   restaurant-assets/{restaurant_id}/cover.{ext}
--   menu-items/{restaurant_id}/{menu_item_id}.{ext}
--
-- The migration is safe to re-run.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. Buckets
-- ---------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('restaurant-assets', 'restaurant-assets', true, 5242880, array['image/jpeg','image/png','image/webp']),
  ('menu-items',        'menu-items',        true, 5242880, array['image/jpeg','image/png','image/webp'])
on conflict (id) do nothing;

-- ---------------------------------------------------------------------
-- 2. Helper: restaurant id encoded in the first folder segment
-- ---------------------------------------------------------------------
-- Returns null instead of raising when a caller targets a malformed path, so
-- the policy simply denies the write.
create or replace function public.storage_folder_restaurant_id(p_name text)
returns uuid
language plpgsql
immutable
set search_path = public
as $$
declare
  v_segment text;
begin
  v_segment := split_part(p_name, '/', 1);
  begin
    return v_segment::uuid;
  exception when invalid_text_representation then
    return null;
  end;
end;
$$;

-- ---------------------------------------------------------------------
-- 3. storage.objects policies
-- ---------------------------------------------------------------------
drop policy if exists "storage_public_read_project_images" on storage.objects;
create policy "storage_public_read_project_images"
  on storage.objects for select
  using (bucket_id in ('restaurant-assets', 'menu-items'));

drop policy if exists "storage_staff_write_restaurant_assets" on storage.objects;
create policy "storage_staff_write_restaurant_assets"
  on storage.objects for all
  to authenticated
  using (
    bucket_id = 'restaurant-assets'
    and public.is_staff_of(public.storage_folder_restaurant_id(name))
  )
  with check (
    bucket_id = 'restaurant-assets'
    and public.is_staff_of(public.storage_folder_restaurant_id(name))
  );

drop policy if exists "storage_staff_write_menu_items" on storage.objects;
create policy "storage_staff_write_menu_items"
  on storage.objects for all
  to authenticated
  using (
    bucket_id = 'menu-items'
    and public.is_staff_of(public.storage_folder_restaurant_id(name))
  )
  with check (
    bucket_id = 'menu-items'
    and public.is_staff_of(public.storage_folder_restaurant_id(name))
  );

-- ===========================================================================
-- Source: supabase/migrations/0006_restaurants_manager_update.sql
-- ===========================================================================

-- =====================================================================
-- QuickTab Admin — Manager access to restaurant settings (D1)
-- ---------------------------------------------------------------------
-- Run AFTER 0005_storage.sql in the Supabase SQL editor.
--
-- Owners and managers may update the profile/branding fields of their
-- restaurant. Owner-only fields (owner_id, slug, is_active) remain
-- owner-only and are enforced by a trigger, not just by the UI.
--
-- The migration is safe to re-run.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. is_manager_of()
-- ---------------------------------------------------------------------
create or replace function public.is_manager_of(p_restaurant_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    public.is_owner_of(p_restaurant_id)
    or exists (
      select 1
      from public.restaurant_staff rs
      where rs.restaurant_id = p_restaurant_id
        and rs.user_id       = auth.uid()
        and rs.is_active
        and rs.role in ('owner', 'manager')
    );
$$;

-- ---------------------------------------------------------------------
-- 2. restaurants update policy
-- ---------------------------------------------------------------------
drop policy if exists "restaurants_owner_update" on public.restaurants;
drop policy if exists "restaurants_staff_update" on public.restaurants;

create policy "restaurants_staff_update"
  on public.restaurants for update
  using      ( public.is_manager_of(id) )
  with check ( public.is_manager_of(id) );

-- ---------------------------------------------------------------------
-- 3. Guard owner-only columns
-- ---------------------------------------------------------------------
create or replace function public.guard_restaurants_owner_fields()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  caller_is_privileged boolean;
begin
  if new.owner_id  is distinct from old.owner_id
     or new.slug      is distinct from old.slug
     or new.is_active is distinct from old.is_active then

    caller_is_privileged :=
      -- Trusted backend (service_role key) or a direct SQL session (dashboard).
      auth.role() = 'service_role'
      or session_user in ('postgres', 'supabase_admin')
      or public.is_owner_of(old.id);

    if not caller_is_privileged then
      raise exception 'Only the restaurant owner can change slug, owner, or active status'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists guard_restaurants_owner_fields on public.restaurants;
create trigger guard_restaurants_owner_fields
  before update on public.restaurants
  for each row execute function public.guard_restaurants_owner_fields();

-- ===========================================================================
-- Source: supabase/migrations/0007_onboarding_rpc.sql
-- ===========================================================================

-- =====================================================================
-- QuickTab Admin — Atomic restaurant onboarding (A6)
-- ---------------------------------------------------------------------
-- Run AFTER 0006_restaurants_manager_update.sql in the Supabase SQL editor.
--
-- Replaces the client's two-write onboarding (restaurant + owner membership)
-- with one security-definer function so a failed second insert cannot leave
-- an orphan restaurant behind.
--
-- The migration is safe to re-run.
-- =====================================================================

create or replace function public.create_restaurant_with_owner(
  p_name text,
  p_slug text
)
returns public.restaurants
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id    uuid := auth.uid();
  v_name       text := btrim(coalesce(p_name, ''));
  v_slug       text := btrim(coalesce(p_slug, ''));
  v_restaurant public.restaurants;
begin
  if v_user_id is null then
    raise exception 'You must be signed in to create a restaurant'
      using errcode = '42501';
  end if;

  if v_name = '' then
    raise exception 'Restaurant name is required'
      using errcode = '22023';
  end if;

  if v_slug = '' then
    raise exception 'Restaurant web address is required'
      using errcode = '22023';
  end if;

  if not exists (select 1 from public.profiles p where p.id = v_user_id) then
    raise exception 'Your profile is not ready yet. Please try again.'
      using errcode = 'P0002';
  end if;

  begin
    insert into public.restaurants (owner_id, slug, name)
    values (v_user_id, v_slug, v_name)
    returning * into v_restaurant;
  exception when unique_violation then
    raise exception 'That web address is already taken. Choose another one.'
      using errcode = '23505';
  end;

  insert into public.restaurant_staff (restaurant_id, user_id, role, is_active)
  values (v_restaurant.id, v_user_id, 'owner', true)
  on conflict (restaurant_id, user_id) do update
    set role = 'owner', is_active = true;

  return v_restaurant;
end;
$$;

revoke all on function public.create_restaurant_with_owner(text, text) from public;
revoke all on function public.create_restaurant_with_owner(text, text) from anon;
grant execute on function public.create_restaurant_with_owner(text, text) to authenticated;

